import java.util.random.RandomGenerator

object Strategy {
  fun chooseMove(turn: Int, myHistory: String, opponentHistory: String, rng: RandomGenerator): String {
    if (turn != myHistory.length || myHistory.length != opponentHistory.length) return "X"
    if (!(myHistory + opponentHistory).all { it in "RPS" }) return "X"
    return arrayOf("R", "P", "S")[turn % 3]
  }
}

